#include <stdio.h>
int main(void) {
    int n = printf("[%6.2f|%-4d|%+d]", 3.14159, 7, 5);
    printf(" %d\n", n);
    n = printf("%#o %#x % d", 8, 255, 42);
    printf(" %d\n", n);
    return 0;
}

#include <stdio.h>
int main(void) {
    char buf[40], name[10];
    int d, m, y;
    int k = sscanf("12-05-2024 Ram", "%d-%d-%d %9s", &d, &m, &y, name);
    int len = sprintf(buf, "%s:%02d/%02d/%d", name, m, d, y % 100);
    printf("%d %s %d\n", k, buf, len);
    return 0;
}

questions.questionText:
Assume the ASCII character set. What is the output of the following fragment?
char c = 'A' + 2;
printf("%c %d %c", c, c, c + 32);

What does the following fragment display?
printf("A");
puts("B");
printf("C");

The user types Ram Bahadur and presses Enter. What does the following fragment print?
char name[20];
scanf("%19s", name);
printf("[%s]", name);

Assume int and unsigned int are 32 bits. What is the output of the following fragment?
unsigned int u = -1;
printf("%u %x", u, u);

What is the output of the following fragment?
int n = printf("[%5d]", 42);
printf(" %d", n);

The user types C is fun and presses Enter. What does the following fragment print?
int c, n = 0;
while ((c = getchar()) != '\n')
    if (c != ' ')
        n++;
printf("%d", n);

The user types 7 x9 and presses Enter. What does the following fragment print?
int a = 1, b = 2;
int k = scanf("%d %d", &a, &b);
printf("%d %d %d", k, a, b);

The user types 10 20 30 and presses Enter. What does the following fragment print?
int x = 0, y = 0;
int k = scanf("%d %*d %d", &x, &y);
printf("%d %d %d", k, x, y);

The user types 5 x y and presses Enter. What does the following fragment print?
int n;
char a, b;
scanf("%d%c %c", &n, &a, &b);
printf("%d[%c][%c]", n, a, b);

What is the output of the following fragment?
char buf[20];
int n = sprintf(buf, "%d+%d=%d", 12, 30, 12 + 30);
printf("%s %d", buf, n);

The user types exam and presses Enter. What does the following fragment print?
char s[10];
fgets(s, sizeof s, stdin);
printf("%d", (int)strlen(s));

The user types 1234567 89 and presses Enter. What does the following fragment print?
int a = 0, b = 0, c = 0;
scanf("%2d%3d%d", &a, &b, &c);
printf("%d %d %d", a, b, c);

The user types 010 0x1A 010 and presses Enter. What does the following fragment print?
int a, b, c;
scanf("%i %i %d", &a, &b, &c);
printf("%d %d %d", a, b, c);

What is the output of the following fragment?
char item[10];
int qty;
float price;
int k = sscanf("pen,12,7.5", "%9[^,],%d,%f", item, &qty, &price);
printf("%d %s %.2f", k, item, qty * price);

What is the output of the following fragment?
char s[6];
int n = snprintf(s, sizeof s, "%s-%d", "NEC", 2024);
printf("%s %d", s, n);

The user types Kathmandu and presses Enter. What does the following fragment print?
char a[5], b[5];
fgets(a, sizeof a, stdin);
fgets(b, sizeof b, stdin);
printf("%s|%s", a, b);
